<?php
require_once __DIR__.'/../includes/bootstrap.php'; require_role('admin');
if($_SERVER['REQUEST_METHOD']==='POST') {
    $username=trim($_POST['username']??''); $email=trim($_POST['email']??''); $emailDb=$email!==''?$email:null; $name=trim($_POST['name']??''); $pass=$_POST['password']??'';
    if($username===''||$name===''||!password_is_valid($pass)||($email!==''&&!filter_var($email,FILTER_VALIDATE_EMAIL))) flash('Enter a username, full name, valid optional email, and a strong password.','error');
    else { try { $role='teacher'; $hash=password_hash($pass,PASSWORD_DEFAULT); $mustChange=1; $q=$conn->prepare('INSERT INTO users(username,email,password,role,must_change_password) VALUES(?,?,?,?,?)'); $q->bind_param('ssssi',$username,$emailDb,$hash,$role,$mustChange); $q->execute(); $uid=$conn->insert_id; $q=$conn->prepare('INSERT INTO teacher_profiles(user_id,full_name) VALUES(?,?)'); $q->bind_param('is',$uid,$name); $q->execute(); audit($conn,$_SESSION['user_id'],'teacher_created','user',(int)$uid); flash('Teacher account created. Provide the initial password securely; the teacher must replace it at first sign-in.'); } catch(Throwable $e) { flash('Could not create account. Username or email may already be in use.','error'); } }
    go('/spi/admin/teachers.php');
}
page_start('Teachers'); echo '<h1>Teacher accounts</h1><section class="card"><h2>Create teacher</h2><form method="post"><input type="hidden" name="csrf" value="'.e(csrf_token()).'"><div class="formgrid"><label>Full name<input name="name" required></label><label>Username<input name="username" required></label><label>Email (optional)<input type="email" name="email"></label><label>Initial password<div class="password-field"><input id="teacher-initial-password" type="password" name="password" minlength="8" maxlength="128" required>'.password_toggle('teacher-initial-password').'</div>'.password_meter('teacher-initial-password').'</label></div><button>Create</button></form></section><div class="tablewrap"><table><tr><th>Name</th><th>Username</th><th>Email</th><th>Status</th></tr>';
$rows=$conn->query("SELECT u.user_id,u.username,u.email,u.account_status,p.full_name FROM users u JOIN teacher_profiles p ON p.user_id=u.user_id ORDER BY p.full_name"); while($r=$rows->fetch_assoc()) echo '<tr><td>'.e($r['full_name']).'</td><td>'.e($r['username']).'</td><td>'.e($r['email']).'</td><td>'.e($r['account_status']).'</td></tr>'; echo '</table></div>'; page_end();
